`,Sy=`// The site side of the Browser's message protocol (src/core/browser/bridge.ts),
// as an in-game site would include it from the SDK. The page is sandboxed: it
// tells the Browser which page it is, and asks it to follow links and to
// download the site's files. The Browser checks every message.
(function () {
  'use strict';
  var meta = document.querySelector('meta[name="prism-url"]');
  var here = meta ? meta.getAttribute('content') || '' : '';
  var post = function (message) {
    message.channel = 'prism-site';
    window.parent.postMessage(message, '*');
  };
  post({ type: 'page', url: here, title: document.title });
  document.addEventListener('click', function (event) {
    var target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    var file = target.closest('[data-download]');
    if (file) {
      event.preventDefault();
      post({ type: 'download', fileId: file.getAttribute('data-download') || '' });
      return;
    }
    var link = target.closest('a[href]');
    if (!link) return;
    event.preventDefault();
    var url;
    try {
      url = new URL(link.getAttribute('href') || '', here).href;
    } catch {
      return;
    }
    post({ type: 'open', url: url, newTab: link.getAttribute('target') === '_blank' });
  });
})();
